import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Business {
  name: string;
  address: string;
  rating: number;
  reviewCount: number;
  websiteUri?: string; // Optional because the goal is to find ones without it
  type: string;
  placeId?: string;
  summary?: string;
}

export interface WebsiteContent {
  businessName: string;
  tagline: string;
  heroHeadline: string;
  heroSubheadline: string;
  aboutText: string;
  services: Array<{
    title: string;
    description: string;
    icon: 'wrench' | 'star' | 'coffee' | 'scissors' | 'home' | 'car' | 'users' | 'zap'; 
  }>;
  testimonials: Array<{
    text: string;
    author: string;
  }>;
  contactInfo: {
    address: string;
    phone: string;
    email: string;
    hours: string;
  };
  colorPalette: {
    primary: string;
    secondary: string;
    accent: string;
    background: string;
    text: string;
  };
  fontStyle: 'modern' | 'classic' | 'playful';
}

export type AppStep = 'search' | 'results' | 'generating' | 'preview';

import { GoogleGenAI, Type } from "@google/genai";
import { Business, WebsiteContent } from "../types";

// Initialize Gemini Client
const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Searches for businesses using Google Maps Grounding via Gemini 2.5 Flash.
 */
export const searchBusinesses = async (
  query: string,
  location: string
): Promise<Business[]> => {
  const ai = getClient();
  const prompt = `
    Find 10 popular and highly-rated "${query}" businesses in or near "${location}".
    I am specifically looking for "thriving" businesses that might need a website update or don't have one.

    Return a JSON array where each object has:
    - name (string)
    - address (string)
    - rating (number)
    - reviewCount (number)
    - websiteUri (string, use empty string if not found or if it looks like a generic facebook/yelp link)
    - type (string, e.g., "Italian Restaurant", "Plumber")
    - summary (string, a brief 1 sentence summary of what they are known for based on reviews)

    Strictly return ONLY the JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) return [];

    // Parse the JSON response
    const businesses: Business[] = JSON.parse(text);
    return businesses;
  } catch (error) {
    console.error("Error searching businesses:", error);
    throw error;
  }
};

/**
 * Generates website content and design structure using Gemini 3 Pro with Thinking Mode.
 */
export const generateWebsiteContent = async (
  business: Business
): Promise<WebsiteContent> => {
  const ai = getClient();

  const prompt = `
    You are a world-class web designer and copywriter. 
    I need you to architect a professional single-page website for a local business.

    Business Details:
    Name: ${business.name}
    Type: ${business.type}
    Address: ${business.address}
    Existing Rating: ${business.rating} (${business.reviewCount} reviews)
    Known for: ${business.summary || "Quality service"}

    Task:
    Create a complete content strategy and design system for this business. 
    The tone should be professional, inviting, and trustworthy, tailored to the specific industry (${business.type}).
    Since they are a thriving local business, emphasize their reputation and local presence.

    Output a JSON object matching this schema:
    {
      "businessName": string,
      "tagline": string (catchy, short),
      "heroHeadline": string (compelling hook),
      "heroSubheadline": string (supporting value prop),
      "aboutText": string (2-3 paragraphs, compelling story based on their type/location),
      "services": [ { "title": string, "description": string, "icon": "one of: wrench, star, coffee, scissors, home, car, users, zap" } ] (3-4 key services),
      "testimonials": [ { "text": string, "author": string } ] (Generate 3 realistic testimonials that reflect their high rating),
      "contactInfo": {
        "address": string (use real one provided),
        "phone": string (placeholder if unknown),
        "email": string (placeholder),
        "hours": string (typical hours for this industry)
      },
      "colorPalette": {
        "primary": string (hex code),
        "secondary": string (hex code),
        "accent": string (hex code),
        "background": string (hex code, usually light),
        "text": string (hex code, usually dark)
      },
      "fontStyle": "one of: modern, classic, playful"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 32768 }, // Max thinking for complex architectural task
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    const content: WebsiteContent = JSON.parse(text);
    return content;
  } catch (error) {
    console.error("Error generating website:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { Search as SearchIcon, MapPin, Loader2 } from 'lucide-react';

interface SearchProps {
  onSearch: (query: string, location: string) => Promise<void>;
  isLoading: boolean;
}

const Search: React.FC<SearchProps> = ({ onSearch, isLoading }) => {
  const [query, setQuery] = useState('');
  const [location, setLocation] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query && location) {
      onSearch(query, location);
    }
  };

  const handleGeolocate = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          // Simple reverse geocode heuristic or just use "Current Location" 
          // For this demo, let's just pre-fill a known format or let the model handle lat/long if we passed it.
          // To keep it simple for the text input:
          setLocation(`${position.coords.latitude.toFixed(4)}, ${position.coords.longitude.toFixed(4)}`);
        },
        (error) => {
          console.error("Error getting location", error);
          alert("Could not get location. Please enter manually.");
        }
      );
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-2xl shadow-xl p-8 transform transition-all hover:scale-[1.01]">
      <div className="text-center mb-8">
        <h2 className="text-3xl font-bold text-slate-800 mb-2">Find Local Businesses</h2>
        <p className="text-slate-500">Scan Google Maps for thriving businesses that need a professional web presence.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Business Type</label>
          <div className="relative">
            <SearchIcon className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="e.g. Plumbers, Bakeries, Auto Repair"
              className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
              required
            />
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Location</label>
          <div className="relative">
            <MapPin className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="text"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              placeholder="e.g. Chicago, IL or Zip Code"
              className="w-full pl-10 pr-12 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
              required
            />
            <button
              type="button"
              onClick={handleGeolocate}
              className="absolute right-3 top-2.5 p-1 text-slate-400 hover:text-indigo-600 transition-colors"
              title="Use current location"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/><circle cx="12" cy="10" r="3"/></svg>
            </button>
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-3 px-6 rounded-xl shadow-lg shadow-indigo-200 transition-all flex items-center justify-center space-x-2 disabled:opacity-70 disabled:cursor-not-allowed mt-6"
        >
          {isLoading ? (
            <>
              <Loader2 className="animate-spin h-5 w-5" />
              <span>Scanning Maps...</span>
            </>
          ) : (
            <span>Start Scan</span>
          )}
        </button>
      </form>
    </div>
  );
};

export default Search;

import React from 'react';
import { Business } from '../types';
import { Star, Globe, AlertCircle, ArrowRight, CheckCircle2 } from 'lucide-react';

interface BusinessListProps {
  businesses: Business[];
  onSelect: (business: Business) => void;
}

const BusinessList: React.FC<BusinessListProps> = ({ businesses, onSelect }) => {
  if (businesses.length === 0) {
    return (
      <div className="text-center py-12">
        <div className="bg-slate-100 rounded-full h-16 w-16 flex items-center justify-center mx-auto mb-4">
          <AlertCircle className="h-8 w-8 text-slate-400" />
        </div>
        <h3 className="text-lg font-medium text-slate-900">No businesses found</h3>
        <p className="text-slate-500">Try adjusting your search terms or location.</p>
      </div>
    );
  }

  // Sort: Businesses without websites first, then by rating
  const sortedBusinesses = [...businesses].sort((a, b) => {
    const aHasSite = !!a.websiteUri;
    const bHasSite = !!b.websiteUri;
    if (aHasSite !== bHasSite) return aHasSite ? 1 : -1;
    return b.rating - a.rating;
  });

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Scan Results</h2>
        <span className="bg-indigo-100 text-indigo-800 text-sm font-medium px-3 py-1 rounded-full">
          {businesses.length} Found
        </span>
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {sortedBusinesses.map((business, index) => {
          const hasWebsite = !!business.websiteUri && business.websiteUri !== '';
          const isHighPotential = !hasWebsite && business.rating > 4.0 && business.reviewCount > 10;

          return (
            <div 
              key={index} 
              className={`relative bg-white rounded-xl p-6 shadow-sm border-2 transition-all hover:shadow-md cursor-pointer group flex flex-col justify-between
                ${isHighPotential ? 'border-green-400 ring-4 ring-green-50/50' : 'border-transparent hover:border-indigo-100'}
              `}
              onClick={() => onSelect(business)}
            >
              {isHighPotential && (
                <div className="absolute -top-3 left-1/2 transform -translate-x-1/2 bg-green-500 text-white text-xs font-bold px-3 py-1 rounded-full shadow-sm flex items-center gap-1">
                   <CheckCircle2 size={12} /> High Potential
                </div>
              )}

              <div>
                <div className="flex justify-between items-start mb-2">
                  <h3 className="font-bold text-lg text-slate-900 leading-tight group-hover:text-indigo-600 transition-colors">
                    {business.name}
                  </h3>
                </div>

                <p className="text-sm text-slate-500 mb-3">{business.type}</p>

                <div className="flex items-center space-x-1 mb-4">
                  <Star className="h-4 w-4 text-amber-400 fill-current" />
                  <span className="font-bold text-slate-700">{business.rating}</span>
                  <span className="text-slate-400 text-sm">({business.reviewCount} reviews)</span>
                </div>

                <div className="text-sm text-slate-600 mb-4 line-clamp-2 min-h-[40px]">
                  {business.summary || "No summary available."}
                </div>
              </div>

              <div className="mt-auto">
                 <div className={`flex items-center space-x-2 text-sm mb-4 ${hasWebsite ? 'text-green-600' : 'text-rose-500'}`}>
                  <Globe className="h-4 w-4" />
                  <span className="font-medium truncate max-w-[200px]">
                    {hasWebsite ? business.websiteUri : 'No Website Detected'}
                  </span>
                </div>

                <button className="w-full py-2 px-4 bg-slate-50 hover:bg-indigo-600 hover:text-white text-slate-700 font-medium rounded-lg transition-colors flex items-center justify-center gap-2 border border-slate-200 hover:border-transparent">
                  Generate Site <ArrowRight size={16} />
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default BusinessList;

import React, { useState } from 'react';
import { Business, WebsiteContent, AppStep } from './types';
import { searchBusinesses, generateWebsiteContent } from './services/geminiService';
import Search from './components/Search';
import BusinessList from './components/BusinessList';
import WebsitePreview from './components/WebsitePreview';
import { Map, Sparkles, AlertTriangle, ArrowLeft } from 'lucide-react';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('search');
  const [businesses, setBusinesses] = useState<Business[]>([]);
  const [selectedBusiness, setSelectedBusiness] = useState<Business | null>(null);
  const [websiteContent, setWebsiteContent] = useState<WebsiteContent | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async (query: string, location: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const results = await searchBusinesses(query, location);
      setBusinesses(results);
      setStep('results');
    } catch (err) {
      setError("Failed to fetch businesses. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSelectBusiness = async (business: Business) => {
    setSelectedBusiness(business);
    setStep('generating');
    setIsLoading(true);

    // Simulate "Think" delay for UI drama if API is too fast, but usually Gemini Pro needs time.
    try {
      const content = await generateWebsiteContent(business);
      setWebsiteContent(content);
      setStep('preview');
    } catch (err) {
      setError("Failed to generate website content.");
      setStep('results');
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setStep('search');
    setBusinesses([]);
    setSelectedBusiness(null);
    setWebsiteContent(null);
  };

  // Render Logic

  if (step === 'preview' && websiteContent) {
    return <WebsitePreview content={websiteContent} onReset={() => setStep('results')} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">

      {/* Header */}
      <header className="bg-white border-b border-slate-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 cursor-pointer" onClick={handleReset}>
            <div className="bg-indigo-600 p-1.5 rounded-lg">
              <Map className="h-6 w-6 text-white" />
            </div>
            <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
              LocalBiz WebGen
            </span>
          </div>
          {step !== 'search' && (
            <button onClick={handleReset} className="text-sm font-medium text-slate-500 hover:text-indigo-600">
              New Search
            </button>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* Step: Search */}
        {step === 'search' && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] animate-fadeIn">
            <Search onSearch={handleSearch} isLoading={isLoading} />
            {error && (
              <div className="mt-4 p-4 bg-red-50 text-red-600 rounded-lg flex items-center gap-2">
                <AlertTriangle className="h-5 w-5" />
                {error}
              </div>
            )}
          </div>
        )}

        {/* Step: Results */}
        {step === 'results' && (
          <div>
            <div className="mb-6 flex items-center gap-4">
              <button 
                onClick={handleReset} 
                className="p-2 hover:bg-slate-200 rounded-full transition-colors"
                title="Back to search"
              >
                <ArrowLeft className="h-5 w-5 text-slate-600" />
              </button>
              <h2 className="text-xl font-semibold">Select a business to modernize</h2>
            </div>
            <BusinessList businesses={businesses} onSelect={handleSelectBusiness} />
          </div>
        )}

        {/* Step: Generating */}
        {step === 'generating' && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fadeIn">
            <div className="relative">
              <div className="absolute inset-0 bg-indigo-500 rounded-full blur-xl opacity-20 animate-pulse"></div>
              <div className="relative bg-white p-6 rounded-full shadow-xl">
                 <Sparkles className="h-12 w-12 text-indigo-600 animate-spin-slow" />
              </div>
            </div>

            <div className="max-w-md space-y-4">
              <h2 className="text-2xl font-bold text-slate-800">Designing Website...</h2>
              <div className="text-slate-500 space-y-2">
                <p>Analyzing {selectedBusiness?.name}'s digital footprint.</p>
                <p>Gemini 3 Pro is architecting the layout...</p>
                <p className="text-xs text-indigo-500 uppercase font-semibold tracking-wider">Thinking Mode Active</p>
              </div>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

