const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Searches for businesses using Google Maps Grounding via Gemini 2.5 Flash.
 */
export const searchBusinesses = async (
  query: string,
  location: string
): Promise<Business[]> => {
  const ai = getClient();
  const prompt = `
    Find 10 popular and highly-rated "${query}" businesses in or near "${location}".
    I am specifically looking for "thriving" businesses that might need a website update or don't have one.

    Use the Google Maps tool to find real businesses.

    After finding the businesses, format the output as a JSON array.
    Each object in the array must have:
    - name (string)
    - address (string)
    - rating (number)
    - reviewCount (number)
    - websiteUri (string, use empty string if not found or if it looks like a generic facebook/yelp link)
    - type (string, e.g., "Italian Restaurant", "Plumber")
    - summary (string, a brief 1 sentence summary of what they are known for based on reviews)

    Strictly return ONLY the JSON array. Do not include any other text or markdown code blocks.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        // responseMimeType: "application/json" is NOT supported with googleMaps
      },
    });

    let text = response.text;
    if (!text) return [];

    // Clean markdown code blocks if present (e.g. ```json ... ```)
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    try {
      // Parse the JSON response
      const businesses: Business[] = JSON.parse(text);
      return businesses;
    } catch (parseError) {
      console.error("Failed to parse JSON from Gemini response:", text);
      // Fallback: Try to find a JSON array pattern in the text if simple cleanup failed
      const jsonMatch = text.match(/\[.*\]/s);
      if (jsonMatch) {
          try {
            return JSON.parse(jsonMatch[0]);
          } catch (e) {
            return [];
          }
      }
      return []; 
    }
  } catch (error) {
    console.error("Error searching businesses:", error);
    throw error;
  }
};

