import { GoogleGenAI } from "@google/genai";
import { Business, WebsiteContent } from "../types";

// Helper to get client
const getClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Searches for businesses using Google Maps Grounding via Gemini 2.5 Flash.
 */
export const searchBusinesses = async (
  query: string,
  location: string
): Promise<Business[]> => {
  const ai = getClient();
  const prompt = `
    Find 10 popular and highly-rated "${query}" businesses in or near "${location}".
    I am specifically looking for "thriving" businesses (4.0+ stars, 20+ reviews) that might be missing a website or have a poor online presence.

    Use the Google Maps tool to find real businesses details.

    After finding the businesses, format the output as a strictly valid JSON array.
    Each object in the array must have:
    - name (string)
    - address (string)
    - rating (number)
    - reviewCount (number)
    - websiteUri (string, use empty string "" if not found)
    - type (string, e.g., "Italian Restaurant", "Plumber")
    - summary (string, a brief 1 sentence summary)

    Strictly return ONLY the JSON array. Do not include markdown formatting.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        // responseMimeType: "application/json" is NOT supported with googleMaps
      },
    });

    // response.text is a property, not a function
    let text = response.text;
    if (!text) return [];

    // Clean markdown code blocks if present
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    try {
      // Find the JSON array pattern
      const jsonMatch = text.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return JSON.parse(text);
    } catch (parseError) {
      console.error("Failed to parse JSON from Gemini response:", text);
      return []; 
    }
  } catch (error) {
    console.error("Error searching businesses:", error);
    throw error; // Propagate error to UI
  }
};

/**
 * Generates a professional image for the business using Gemini 2.5 Flash Image.
 */
export const generateBusinessImage = async (prompt: string): Promise<string | undefined> => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
        imageConfig: { aspectRatio: '16:9' }
      }
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return part.inlineData.data;
        }
      }
    }
  } catch (error) {
    console.error("Error generating image:", error);
  }
  return undefined;
};

/**
 * Edits an existing image using a text prompt via Gemini 2.5 Flash Image.
 */
export const editBusinessImage = async (imageBase64: string, prompt: string): Promise<string | undefined> => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png',
              data: imageBase64,
            },
          },
          { text: prompt },
        ],
      },
      config: {
        imageConfig: { aspectRatio: '16:9' }
      }
    });

     if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return part.inlineData.data;
        }
      }
    }
  } catch (error) {
    console.error("Error editing image:", error);
    throw error;
  }
  return undefined;
};

/**
 * Generates website content and design structure using Gemini 3 Pro with Thinking Mode.
 */
export const generateWebsiteContent = async (
  business: Business
): Promise<WebsiteContent> => {
  const ai = getClient();

  const textPrompt = `
    You are a world-class web designer and copywriter building a Next.js + Tailwind site.
    Architect a professional single-page website for:

    Name: ${business.name}
    Type: ${business.type}
    Address: ${business.address}
    Rating: ${business.rating} (${business.reviewCount} reviews)
    Known for: ${business.summary || "Quality service"}

    Output a JSON object for the content strategy:
    {
      "businessName": string,
      "tagline": string,
      "heroHeadline": string,
      "heroSubheadline": string,
      "aboutText": string (2-3 paragraphs),
      "services": [ { "title": string, "description": string, "icon": "wrench|star|coffee|scissors|home|car|users|zap" } ],
      "testimonials": [ { "text": string, "author": string } ],
      "contactInfo": { "address": string, "phone": string, "email": string, "hours": string },
      "colorPalette": { "primary": string, "secondary": string, "accent": string, "background": string, "text": string },
      "fontStyle": "modern|classic|playful"
    }
  `;

  const imagePrompt = `A professional, photorealistic hero image for a ${business.type} named "${business.name}". High quality, modern website header style. ${business.summary || ''}`;

  try {
    // Parallel generation
    const [textResponse, imageBase64] = await Promise.all([
      ai.models.generateContent({
        model: "gemini-3-pro-preview",
        contents: textPrompt,
        config: {
          thinkingConfig: { thinkingBudget: 16384 }, 
          responseMimeType: "application/json",
        },
      }),
      generateBusinessImage(imagePrompt)
    ]);

    const text = textResponse.text;
    if (!text) throw new Error("No content generated");

    const content: WebsiteContent = JSON.parse(text);

    if (imageBase64) {
      content.heroImageBase64 = imageBase64;
    }

    return content;
  } catch (error) {
    console.error("Error generating website:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Business, WebsiteContent, AppStep } from './types';
import { searchBusinesses, generateWebsiteContent } from './services/geminiService';
import Search from './components/Search';
import BusinessList from './components/BusinessList';
import WebsitePreview from './components/WebsitePreview';
import { Map, Sparkles, AlertTriangle, ArrowLeft, Trash2 } from 'lucide-react';

const App: React.FC = () => {
  // Initialize state from localStorage if available
  const [step, setStep] = useState<AppStep>(() => 
    (localStorage.getItem('lb_step') as AppStep) || 'search'
  );

  const [businesses, setBusinesses] = useState<Business[]>(() => {
    const saved = localStorage.getItem('lb_businesses');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedBusiness, setSelectedBusiness] = useState<Business | null>(() => {
    const saved = localStorage.getItem('lb_selectedBusiness');
    return saved ? JSON.parse(saved) : null;
  });

  const [websiteContent, setWebsiteContent] = useState<WebsiteContent | null>(() => {
    const saved = localStorage.getItem('lb_websiteContent');
    return saved ? JSON.parse(saved) : null;
  });

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Persistence Effect
  useEffect(() => {
    localStorage.setItem('lb_step', step);
    localStorage.setItem('lb_businesses', JSON.stringify(businesses));
    localStorage.setItem('lb_selectedBusiness', JSON.stringify(selectedBusiness));
    localStorage.setItem('lb_websiteContent', JSON.stringify(websiteContent));
  }, [step, businesses, selectedBusiness, websiteContent]);

  const handleSearch = async (query: string, location: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const results = await searchBusinesses(query, location);
      setBusinesses(results);
      setStep('results');
    } catch (err) {
      setError("Failed to fetch businesses. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSelectBusiness = async (business: Business) => {
    setSelectedBusiness(business);
    setStep('generating');
    setIsLoading(true);

    try {
      const content = await generateWebsiteContent(business);
      setWebsiteContent(content);
      setStep('preview');
    } catch (err) {
      setError("Failed to generate website content.");
      setStep('results');
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateContent = (newContent: WebsiteContent) => {
    setWebsiteContent(newContent);
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to clear all data and start over?")) {
      setStep('search');
      setBusinesses([]);
      setSelectedBusiness(null);
      setWebsiteContent(null);
      localStorage.clear();
    }
  };

  // Render Logic
  if (step === 'preview' && websiteContent) {
    return (
      <WebsitePreview 
        content={websiteContent} 
        onReset={() => setStep('results')} 
        onUpdate={handleUpdateContent}
      />
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">

      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 cursor-pointer" onClick={() => setStep('search')}>
            <div className="bg-indigo-600 p-1.5 rounded-lg">
              <Map className="h-6 w-6 text-white" />
            </div>
            <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
              LocalBiz WebGen
            </span>
          </div>

          <div className="flex items-center gap-4">
            {step !== 'search' && (
              <button 
                onClick={handleReset} 
                className="flex items-center gap-2 text-sm font-medium text-slate-500 hover:text-red-600 transition-colors px-3 py-1.5 rounded-md hover:bg-red-50"
              >
                <Trash2 size={16} /> Clear & Restart
              </button>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* Step: Search */}
        {step === 'search' && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] animate-fadeIn">
            <Search onSearch={handleSearch} isLoading={isLoading} />
            {error && (
              <div className="mt-4 p-4 bg-red-50 text-red-600 rounded-lg flex items-center gap-2">
                <AlertTriangle className="h-5 w-5" />
                {error}
              </div>
            )}
          </div>
        )}

        {/* Step: Results */}
        {step === 'results' && (
          <div>
            <div className="mb-6 flex items-center gap-4">
              <button 
                onClick={() => setStep('search')} 
                className="p-2 hover:bg-slate-200 rounded-full transition-colors"
                title="Back to search"
              >
                <ArrowLeft className="h-5 w-5 text-slate-600" />
              </button>
              <h2 className="text-xl font-semibold">Select a business to modernize</h2>
            </div>
            <BusinessList businesses={businesses} onSelect={handleSelectBusiness} />
          </div>
        )}

        {/* Step: Generating */}
        {step === 'generating' && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fadeIn">
            <div className="relative">
              <div className="absolute inset-0 bg-indigo-500 rounded-full blur-xl opacity-20 animate-pulse"></div>
              <div className="relative bg-white p-6 rounded-full shadow-xl">
                 <Sparkles className="h-12 w-12 text-indigo-600 animate-spin-slow" />
              </div>
            </div>

            <div className="max-w-md space-y-4">
              <h2 className="text-2xl font-bold text-slate-800">Designing Website...</h2>
              <div className="text-slate-500 space-y-2">
                <p>Analyzing {selectedBusiness?.name}'s digital footprint.</p>
                <p>Gemini 3 Pro is architecting the layout...</p>
                <p className="text-xs text-indigo-500 uppercase font-semibold tracking-wider">Thinking Mode Active</p>
              </div>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

