import React, { useState } from 'react';
import { WebsiteContent } from '../types';
import { editBusinessImage } from '../services/geminiService';
import { Wrench, Star, Coffee, Scissors, Home, Car, Users, Zap, Menu, X, Phone, Mail, MapPin, Facebook, Instagram, Twitter, ImagePlus, Loader2, Sparkles, RefreshCw, Edit3, Settings, Palette, Type, Layout } from 'lucide-react';

interface WebsitePreviewProps {
  content: WebsiteContent;
  onReset: () => void;
  onUpdate: (content: WebsiteContent) => void;
}

const IconMap = {
  wrench: Wrench,
  star: Star,
  coffee: Coffee,
  scissors: Scissors,
  home: Home,
  car: Car,
  users: Users,
  zap: Zap
};

const WebsitePreview: React.FC<WebsitePreviewProps> = ({ content, onReset, onUpdate }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'desktop' | 'mobile'>('desktop');
  const [showImageEdit, setShowImageEdit] = useState(false);
  const [showEditor, setShowEditor] = useState(false);
  const [editPrompt, setEditPrompt] = useState('');
  const [isEditingImage, setIsEditingImage] = useState(false);

  const {
    colorPalette,
    fontStyle,
    businessName,
    heroHeadline,
    heroSubheadline,
    aboutText,
    services,
    testimonials,
    contactInfo,
    heroImageBase64
  } = content;

  // --- Image Editor Handler ---
  const handleImageEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!heroImageBase64 || !editPrompt) return;

    setIsEditingImage(true);
    try {
      const newImage = await editBusinessImage(heroImageBase64, editPrompt);
      if (newImage) {
        onUpdate({ ...content, heroImageBase64: newImage });
        setShowImageEdit(false);
        setEditPrompt('');
      }
    } catch (error) {
      alert("Failed to edit image. Please try again.");
    } finally {
      setIsEditingImage(false);
    }
  };

  // --- Content Editor Handlers ---
  const updateField = (section: keyof WebsiteContent, value: any) => {
    onUpdate({ ...content, [section]: value });
  };

  const updateNestedField = (section: keyof WebsiteContent, key: string, value: string) => {
    const sectionData = content[section] as any;
    onUpdate({
      ...content,
      [section]: { ...sectionData, [key]: value }
    });
  };

  // --- Style Utilities ---
  const fontClass = 
    fontStyle === 'modern' ? 'font-sans' :
    fontStyle === 'classic' ? 'font-serif' :
    'font-mono';

  const primaryStyle = { backgroundColor: colorPalette.primary, color: '#ffffff' };

  // --- Editor Sidebar Component ---
  const EditorSidebar = () => (
    <div className={`fixed inset-y-0 right-0 w-80 bg-white shadow-2xl z-[60] transform transition-transform duration-300 overflow-y-auto border-l border-slate-200 ${showEditor ? 'translate-x-0' : 'translate-x-full'}`}>
      <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
        <h3 className="font-bold text-slate-800 flex items-center gap-2">
          <Settings size={18} /> Site Editor
        </h3>
        <button onClick={() => setShowEditor(false)} className="text-slate-400 hover:text-slate-600">
          <X size={20} />
        </button>
      </div>

      <div className="p-4 space-y-6">
        {/* Identity Section */}
        <div className="space-y-3">
          <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
            <Layout size={14} /> Identity
          </h4>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Business Name</label>
            <input 
              type="text" 
              value={businessName}
              onChange={(e) => updateField('businessName', e.target.value)}
              className="w-full text-sm p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Tagline</label>
            <input 
              type="text" 
              value={content.tagline}
              onChange={(e) => updateField('tagline', e.target.value)}
              className="w-full text-sm p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
        </div>

        {/* Hero Section */}
        <div className="space-y-3 pt-4 border-t border-slate-100">
           <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
            <Type size={14} /> Hero Text
          </h4>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Headline</label>
            <textarea 
              rows={2}
              value={heroHeadline}
              onChange={(e) => updateField('heroHeadline', e.target.value)}
              className="w-full text-sm p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Subheadline</label>
            <textarea 
              rows={3}
              value={heroSubheadline}
